  --primary: oklch(56% 0.23 280);
  --primary-strong: oklch(49% 0.24 280);
  --primary-soft: oklch(94% 0.04 282);
  --indigo: oklch(60% 0.16 260);
  --success: oklch(65% 0.16 155);
  --danger: oklch(62% 0.21 28);
