  color: var(--text);
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1160px, 92vw); margin: 0 auto; }
.section { padding: 78px 0; }
.section.alt { background: var(--surface-alt); }
.small { font-size: 0.92rem; color: var(--muted); }
.badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--primary-soft); color: var(--primary-strong);
  border-radius: 999px; padding: 8px 14px; font-weight: 600; font-size: 0.86rem;
}
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px; border-radius: 999px; padding: 12px 22px;
  font-weight: 700; border: 1px solid transparent; cursor: pointer;
  transition: .25s ease; font-size: 0.95rem;
}
.btn.primary { background: linear-gradient(135deg, var(--primary), var(--indigo)); color: #fff; box-shadow: var(--shadow); }
.btn.primary:hover { transform: translateY(-1px); filter: brightness(1.05); }
.btn.ghost { background: var(--surface); border-color: var(--border); }
.btn.ghost:hover { border-color: var(--primary); color: var(--primary-strong); }
.site-header {
  position: sticky; top: 0; z-index: 50; backdrop-filter: blur(8px);
  background: oklch(100% 0 0 / 0.78); border-bottom: 1px solid var(--border);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 11px;
  background: linear-gradient(140deg, var(--primary), var(--indigo));
  position: relative;
}
.brand-mark::after {
  content: ""; position: absolute; inset: 9px; border-radius: 7px;
  border: 2px solid oklch(100% 0 0 / 0.85);
}
.nav-links { display: flex; gap: 24px; align-items: center; font-weight: 600; }
.nav-links a { color: var(--muted); }
.nav-links a:hover, .nav-links a.active { color: var(--primary-strong); }
.nav-actions { display: flex; gap: 10px; }
.hero {
  display: grid; grid-template-columns: 1.15fr 1fr; gap: 30px; align-items: center;
  padding: 72px 0 44px;
