h1 { font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1.06; margin: 12px 0; }
h2 { font-size: clamp(1.45rem, 3vw, 2.3rem); line-height: 1.18; margin: 0 0 12px; }
.lead { font-size: 1.08rem; color: var(--muted); max-width: 58ch; }
.hero-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 22px; padding: 20px; box-shadow: var(--shadow);
}
.mock-video {
  aspect-ratio: 16/10; border-radius: 14px; background:
  radial-gradient(circle at 18% 20%, oklch(82% 0.08 290), transparent 35%),
  radial-gradient(circle at 88% 10%, oklch(90% 0.11 250), transparent 28%),
  linear-gradient(145deg, oklch(96% 0.03 286), oklch(93% 0.04 260));
  border: 1px solid var(--border); position: relative; overflow: hidden;
