.mock-video::after {
  content: ""; position: absolute; width: 76px; height: 76px; border-radius: 50%;
  background: oklch(100% 0 0 / 0.72); border: 2px solid oklch(100% 0 0 / .9);
  top: 50%; left: 50%; transform: translate(-50%, -50%);
}
.grid { display: grid; gap: 18px; }
.grid.cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid.cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 22px; box-shadow: 0 4px 14px oklch(20% 0.04 270 / .03);
}
.card h3 { margin: 10px 0 6px; }
.kpi { font-size: 2rem; font-weight: 800; }
.logos { display: flex; flex-wrap: wrap; gap: 14px; }
.logo-pill { background: var(--surface); border: 1px solid var(--border); padding: 8px 14px; border-radius: 999px; color: var(--muted); font-weight: 600; }
.footer { padding: 34px 0 42px; color: var(--muted); border-top: 1px solid var(--border); margin-top: 30px; }
.pricing-switch { display: inline-flex; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 999px; padding: 4px; gap: 6px; }
.pricing-switch button { border: 0; background: transparent; padding: 9px 16px; border-radius: 999px; font-weight: 700; cursor: pointer; color: var(--muted); }
.pricing-switch button.active { background: var(--surface); color: var(--primary-strong); box-shadow: 0 3px 12px oklch(20% 0.04 270 / .08); }
.plan-price { font-size: 2rem; font-weight: 800; }
.hidden { display: none !important; }
.slider-wrap { display: grid; gap: 12px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; }
input[type="range"] { width: 100%; accent-color: oklch(55% 0.23 280); }
.table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
table { width: 100%; border-collapse: collapse; min-width: 760px; }
th, td { text-align: left; padding: 14px 16px; border-bottom: 1px solid var(--border); }
th { background: var(--surface-alt); font-size: .92rem; }
.faq-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 12px; background: var(--surface); }
.faq-q { width: 100%; border: 0; background: transparent; text-align: left; padding: 14px 16px; font-weight: 700; cursor: pointer; }
.faq-a { padding: 0 16px 16px; color: var(--muted); }
.auth-layout { display: grid; grid-template-columns: 1fr 1fr; min-height: calc(100vh - 72px); }
.auth-panel { display: grid; place-items: center; padding: 30px; }
.auth-card { width: min(460px, 100%); background: var(--surface); border: 1px solid var(--border); border-radius: 18px; padding: 24px; box-shadow: var(--shadow); }
.auth-actions { display: grid; gap: 10px; margin: 18px 0; }
.social { display: flex; align-items: center; justify-content: center; gap: 9px; font-weight: 700; }
.input { width: 100%; border: 1px solid var(--border); border-radius: 12px; padding: 12px 14px; font-size: 1rem; }
.side-quote {
  background: radial-gradient(circle at top right, oklch(89% 0.1 300), transparent 42%),
              linear-gradient(160deg, oklch(95% 0.04 285), oklch(93% 0.05 260));
  padding: clamp(24px, 5vw, 64px); display: flex; align-items: center;
}
.cookie-banner {
  position: fixed; bottom: 18px; left: 50%; transform: translateX(-50%);
  width: min(880px, 92vw); background: var(--surface); border: 1px solid var(--border);
  border-radius: 16px; box-shadow: var(--shadow); padding: 15px; z-index: 70;
  display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between;
}
.modal-backdrop {
  position: fixed; inset: 0; background: oklch(20% 0.02 270 / .42);
  display: none; place-items: center; z-index: 80;
}
.modal { width: min(520px, 90vw); background: var(--surface); border-radius: 16px; border: 1px solid var(--border); padding: 22px; }
.toggle-row { display: flex; justify-content: space-between; align-items: center; padding: 11px 0; border-bottom: 1px solid var(--border); }
.switch { position: relative; width: 46px; height: 26px; }
.switch input { opacity: 0; width: 0; height: 0; }
.knob { position: absolute; inset: 0; border-radius: 99px; background: oklch(84% 0.01 270); cursor: pointer; transition: .2s; }
.knob::after { content: ""; position: absolute; width: 20px; height: 20px; border-radius: 50%; background: #fff; top: 3px; left: 3px; transition: .2s; box-shadow: 0 2px 6px rgba(0,0,0,.2); }
.switch input:checked + .knob { background: var(--primary); }
